[CmdletBinding()]
param(
 [int]$ProjectCount=250,[int]$ProjectListIterations=50,[int]$CollectorIterations=30,[int]$MetricQueryIterations=10,[int]$MetricRows=1000000,
 [int]$BurstRequests=100,[int]$BurstTargetRequestsPerSecond=100,[int]$SoakSeconds=900,[int]$SoakTargetRequestsPerSecond=25,
 [double]$MaxSoakErrorRatePercent=0.1,[double]$MaxSoakMemoryGrowthMb=256,[switch]$UpdateDocumentation,
 [string]$DatabaseHost=$(if($env:POSTGRES_HOST){$env:POSTGRES_HOST}else{'127.0.0.1'}),[int]$DatabasePort=$(if($env:POSTGRES_PORT){[int]$env:POSTGRES_PORT}else{5432}),
 [string]$DatabaseUser=$(if($env:POSTGRES_USER){$env:POSTGRES_USER}else{'dip'}),[string]$DatabasePassword=$(if($env:POSTGRES_PASSWORD){$env:POSTGRES_PASSWORD}else{''}))
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
foreach($v in @($ProjectCount,$ProjectListIterations,$CollectorIterations,$MetricQueryIterations,$MetricRows,$BurstRequests,$BurstTargetRequestsPerSecond,$SoakSeconds,$SoakTargetRequestsPerSecond)){if($v-lt1){throw 'Benchmark numeric parameters must be positive.'}}
$root=(Resolve-Path (Join-Path $PSScriptRoot '..')).Path;$out=Join-Path $root 'artifacts\portfolio-benchmark';New-Item -Force -ItemType Directory $out|Out-Null
foreach($n in 'git','dotnet','psql','pg_isready'){if(-not(Get-Command $n -ErrorAction SilentlyContinue)){throw "$n is required."}}
function FreePort{$l=[Net.Sockets.TcpListener]::new([Net.IPAddress]::Loopback,0);$l.Start();$p=([Net.IPEndPoint]$l.LocalEndpoint).Port;$l.Stop();$p}
function Percentile([double[]]$v,[double]$p){if($v.Count-eq0){return 0};$s=@($v|Sort-Object);$i=[Math]::Max(0,[Math]::Ceiling($s.Count*$p)-1);[Math]::Round($s[$i],3)}
function WaitHttp($url){$d=(Get-Date).AddSeconds(120);do{try{$r=Invoke-WebRequest -UseBasicParsing $url -TimeoutSec 3;if($r.StatusCode-eq200){return}}catch{};Start-Sleep -Milliseconds 500}while((Get-Date)-lt$d);throw "Timed out waiting for $url"}
function PacedSoak($url,$seconds,$rps){$count=$seconds*$rps;$l=@();$e=0;$wall=[Diagnostics.Stopwatch]::StartNew();for($i=0;$i-lt$count;$i++){$target=$i*(1000.0/$rps);while($wall.Elapsed.TotalMilliseconds-lt$target){$remain=$target-$wall.Elapsed.TotalMilliseconds;if($remain-gt2){Start-Sleep -Milliseconds ([Math]::Min(10,[int]$remain))}};$sw=[Diagnostics.Stopwatch]::StartNew();try{$r=Invoke-WebRequest -UseBasicParsing $url -TimeoutSec 10;if($r.StatusCode-ne200){$e++}}catch{$e++}finally{$sw.Stop();$l+=$sw.Elapsed.TotalMilliseconds}};$wall.Stop();[ordered]@{requests=$count;targetRequestsPerSecond=$rps;elapsedSeconds=[Math]::Round($wall.Elapsed.TotalSeconds,3);actualRequestsPerSecond=[Math]::Round($count/$wall.Elapsed.TotalSeconds,3);errors=$e;errorRatePercent=[Math]::Round($e*100.0/$count,4);p50Ms=Percentile $l .5;p95Ms=Percentile $l .95;p99Ms=Percentile $l .99}}
$sha=(& git -C $root rev-parse HEAD|Out-String).Trim();$dirty=[bool]((& git -C $root status --porcelain|Out-String).Trim());$db='dip_bench_'+[guid]::NewGuid().ToString('N').Substring(0,10);$apiPort=FreePort;$apiBase="http://127.0.0.1:$apiPort";$apiProcess=$null;$oldPg=$env:PGPASSWORD;$env:PGPASSWORD=$DatabasePassword
$oldEnv=@{};foreach($n in 'ConnectionStrings__PostgreSql','ASPNETCORE_ENVIRONMENT','ASPNETCORE_URLS','Authentication__RequireAuthenticatedUser','Qa__WorkspaceRoot','Qa__ArtifactRoot','Artifacts__LocalRoot'){$oldEnv[$n]=[Environment]::GetEnvironmentVariable($n,'Process')}
try{
 & pg_isready -h $DatabaseHost -p $DatabasePort -U $DatabaseUser -d postgres *> $null;if($LASTEXITCODE-ne0){throw 'Native PostgreSQL is not ready.'}
 & psql -h $DatabaseHost -p $DatabasePort -U $DatabaseUser -d postgres -v ON_ERROR_STOP=1 -c "CREATE DATABASE \"$db\" OWNER \"$DatabaseUser\";" *> $null;if($LASTEXITCODE-ne0){throw 'Could not create benchmark database. Ensure the DIP role has CREATEDB.'}
 Push-Location $root;try{& dotnet build DevelopmentIntelligencePlatform.sln -c Release --nologo;if($LASTEXITCODE-ne0){throw 'Release build failed.'}}finally{Pop-Location}
 $env:ASPNETCORE_ENVIRONMENT='Benchmark';$env:ASPNETCORE_URLS=$apiBase;$env:Authentication__RequireAuthenticatedUser='false';$env:ConnectionStrings__PostgreSql="Host=$DatabaseHost;Port=$DatabasePort;Database=$db;Username=$DatabaseUser;Password=$DatabasePassword";$env:Qa__WorkspaceRoot=$root;$env:Qa__ArtifactRoot=Join-Path $root 'artifacts\qa';$env:Artifacts__LocalRoot=Join-Path $root 'artifacts\durable'
 $dll=Join-Path $root 'src\Dip.Api\bin\Release\net8.0\Dip.Api.dll';$apiProcess=Start-Process dotnet -ArgumentList @($dll) -WorkingDirectory $root -PassThru;WaitHttp "$apiBase/health"
 $project=$null;for($i=0;$i-lt$ProjectCount;$i++){$body=@{name="Portfolio Benchmark $i";repositoryUrl="https://github.com/example/dip-portfolio-benchmark-$i";defaultBranch='main';releaseDateUtc=$null}|ConvertTo-Json;$created=Invoke-RestMethod -Method Post "$apiBase/api/projects" -ContentType 'application/json' -Body $body;if($i-eq0){$project=$created}}
 1..10|ForEach-Object{Invoke-WebRequest -UseBasicParsing "$apiBase/api/projects"|Out-Null};$projectMs=@();1..$ProjectListIterations|ForEach-Object{$sw=[Diagnostics.Stopwatch]::StartNew();$r=Invoke-WebRequest -UseBasicParsing "$apiBase/api/projects";$sw.Stop();if($r.StatusCode-ne200){throw 'Project list failed'};$projectMs+=$sw.Elapsed.TotalMilliseconds}
 $collectorMs=@();$lastPipeline=$null;1..$CollectorIterations|ForEach-Object{$now=[DateTimeOffset]::UtcNow;$payload=@{schemaVersion='1.0';reportId="bench-$($_)-$([guid]::NewGuid().ToString('N'))";externalRunId="bench-run-$($_)-$([guid]::NewGuid().ToString('N'))";attemptNumber=1;collectorType='portfolio-benchmark';collectorVersion='1.0.0';projectId=$project.id;repository=$project.repositoryUrl;commitSha='0123456789abcdef0123456789abcdef01234567';branch='main';startedAt=$now.AddSeconds(-1);finishedAt=$now;status='Succeeded';metrics=@(@{name='frame_time';value=16.0;unit='ms';baselineValue=16.6;environmentId='portfolio';scenarioId='benchmark';platform='windows';buildConfiguration='Release';benchmarkVersion='1'});issues=@()}|ConvertTo-Json -Depth 8;$sw=[Diagnostics.Stopwatch]::StartNew();$resp=Invoke-RestMethod -Method Post "$apiBase/api/v1/collector-reports" -ContentType 'application/json' -Body $payload;$sw.Stop();$collectorMs+=$sw.Elapsed.TotalMilliseconds;$lastPipeline=$resp.pipelineRunId};if(-not$lastPipeline){throw 'Collector benchmark returned no pipeline id.'}
 Add-Type -AssemblyName System.Net.Http;$client=[Net.Http.HttpClient]::new();$tasks=New-Object System.Collections.ArrayList;$burst=[Diagnostics.Stopwatch]::StartNew();for($i=0;$i-lt$BurstRequests;$i++){$target=$i*(1000.0/$BurstTargetRequestsPerSecond);while($burst.Elapsed.TotalMilliseconds-lt$target){Start-Sleep -Milliseconds 1};[void]$tasks.Add($client.GetAsync("$apiBase/api/projects",[Net.Http.HttpCompletionOption]::ResponseHeadersRead))};[Threading.Tasks.Task]::WaitAll([Threading.Tasks.Task[]]$tasks.ToArray([Threading.Tasks.Task]));$burst.Stop();$burstErrors=0;foreach($t in $tasks){if(-not$t.Result.IsSuccessStatusCode){$burstErrors++};$t.Result.Dispose()};$client.Dispose();$burstErrorRate=[Math]::Round($burstErrors*100.0/$BurstRequests,4)
 $seed=@"
INSERT INTO "Metrics" ("Id","PipelineRunId","BaselinePipelineRunId","Name","Value","Unit","BaselineValue","Difference","DifferencePercent","Severity","ComparisonStatus","EnvironmentId","ScenarioId","Platform","BuildConfiguration","BenchmarkVersion")
SELECT gen_random_uuid(),'$lastPipeline'::uuid,NULL,'portfolio.metric.'||(g%100),(g%1000)::numeric,'ms',NULL,NULL,NULL,0,0,'portfolio','scale-query','windows','Release','1'
FROM generate_series(1,$MetricRows) g;
"@
 $seed|& psql -h $DatabaseHost -p $DatabasePort -U $DatabaseUser -d $db -v ON_ERROR_STOP=1 *> $null;if($LASTEXITCODE-ne0){throw 'Metric seed failed.'}
 $query=@"
SELECT "Name",AVG("Value")
FROM "Metrics"
WHERE "PipelineRunId"='$lastPipeline'::uuid
GROUP BY "Name"
ORDER BY "Name";
"@
 $metricMs=@();1..$MetricQueryIterations|ForEach-Object{$sw=[Diagnostics.Stopwatch]::StartNew();$query|& psql -h $DatabaseHost -p $DatabasePort -U $DatabaseUser -d $db -q -t -v ON_ERROR_STOP=1 *> $null;$sw.Stop();if($LASTEXITCODE-ne0){throw 'Metric query failed'};$metricMs+=$sw.Elapsed.TotalMilliseconds}
 $apiProcess.Refresh();$before=[Math]::Round($apiProcess.WorkingSet64/1MB,3);$soak=PacedSoak "$apiBase/api/projects" $SoakSeconds $SoakTargetRequestsPerSecond;$apiProcess.Refresh();if($apiProcess.HasExited){throw 'API exited during soak'};$after=[Math]::Round($apiProcess.WorkingSet64/1MB,3);$growth=[Math]::Round($after-$before,3)
 $p50=Percentile $projectMs .5;$p95=Percentile $projectMs .95;$p99=Percentile $projectMs .99;$cp95=Percentile $collectorMs .95;$mp95=Percentile $metricMs .95
 $result=[ordered]@{schema='dip-portfolio-benchmark-v3';runtime='native';sourceCommit=$sha;sourceWorkingTreeDirty=$dirty;measuredAtUtc=[DateTimeOffset]::UtcNow.ToString('o');environment=[ordered]@{os=[Environment]::OSVersion.VersionString;processorCount=[Environment]::ProcessorCount;dotnet=(& dotnet --version|Out-String).Trim();database='native-postgresql';redisRequired=$false};scenarios=[ordered]@{projectList=[ordered]@{population=$ProjectCount;iterations=$ProjectListIterations;p50Ms=$p50;p95Ms=$p95;p99Ms=$p99;targetP95Ms=500;passed=$p95-lt500};collector=[ordered]@{iterations=$CollectorIterations;p95Ms=$cp95;targetP95Ms=250;passed=$cp95-lt250};burst=[ordered]@{requests=$BurstRequests;targetRequestsPerSecond=$BurstTargetRequestsPerSecond;elapsedSeconds=[Math]::Round($burst.Elapsed.TotalSeconds,3);errorRatePercent=$burstErrorRate;passed=$burstErrorRate-eq0};metricScale=[ordered]@{rows=$MetricRows;iterations=$MetricQueryIterations;p95Ms=$mp95;targetP95Ms=1000;passed=$mp95-lt1000};soak=$soak;memory=[ordered]@{beforeMb=$before;afterMb=$after;growthMb=$growth;maxGrowthMb=$MaxSoakMemoryGrowthMb;passed=$growth-le$MaxSoakMemoryGrowthMb}};passed=($p95-lt500-and$cp95-lt250-and$burstErrorRate-eq0-and$mp95-lt1000-and$soak.errorRatePercent-le$MaxSoakErrorRatePercent-and$growth-le$MaxSoakMemoryGrowthMb)}
 $json=Join-Path $out 'benchmark-results.json';$result|ConvertTo-Json -Depth 10|Set-Content $json -Encoding UTF8;Write-Host "Native benchmark complete: $json" -ForegroundColor Green;if(-not$result.passed){throw 'One or more benchmark/soak gates failed.'}
 if($UpdateDocumentation){Write-Warning 'Benchmark evidence was measured successfully. Update documentation only after reviewing the exact-SHA JSON artifact; this script does not auto-promote claims.'}
}finally{if($apiProcess-and-not$apiProcess.HasExited){Stop-Process -Id $apiProcess.Id -Force -ErrorAction SilentlyContinue};$env:PGPASSWORD=$oldPg;foreach($n in $oldEnv.Keys){[Environment]::SetEnvironmentVariable($n,$oldEnv[$n],'Process')};& psql -h $DatabaseHost -p $DatabasePort -U $DatabaseUser -d postgres -c "SELECT pg_terminate_backend(pid) FROM pg_stat_activity WHERE datname='$db';" *> $null;& psql -h $DatabaseHost -p $DatabasePort -U $DatabaseUser -d postgres -c "DROP DATABASE IF EXISTS \"$db\";" *> $null}
